reference_solution.limiter.rb:
class TokenBucket
  def initialize(capacity, refill_rate)
    @capacity = capacity
    @refill_rate = refill_rate
    @tokens = capacity.to_f
    @last = nil
  end

  def allow(now)
    unless @last.nil?
      elapsed = now - @last
      @tokens = [@capacity.to_f, @tokens + elapsed * @refill_rate].min
    end
    @last = now
    if @tokens >= 1
      @tokens -= 1
      true
    else
      false
    end
  end
end

